def vincular_archivos(apps, schema_editor):
    """Vincula el formato histórico exacto; nunca inventa una remisión."""
    Recurso = apps.get_model('webcitt', 'Recurso')
    Informe = apps.get_model('webcitt', 'InformeMejora')
    patron = re.compile(r'Informe de incumplimiento y mejora continua · (?:Período (\d{4})-([AB])|Año (\d{4})) · v(\d+)')
    for recurso in Recurso.objects.using(schema_editor.connection.alias).filter(
            nombre__startswith='Informe de incumplimiento y mejora continua · ').iterator():
        coincidencia = patron.fullmatch(recurso.nombre)
        if coincidencia and int(coincidencia[4]) == recurso.version:
            Informe.objects.using(schema_editor.connection.alias).get_or_create(
                recurso_id=recurso.pk, defaults={'unidad_id': recurso.unidad_id,
                'anio': int(coincidencia[1] or coincidencia[3]), 'corte': coincidencia[2] or ''})


